import { Component, Input, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DragDropModule, CdkDragDrop, moveItemInArray, transferArrayItem } from '@angular/cdk/drag-drop';

export interface KanbanColumn {
  id: string;
  title: string;
  items: any[];
}

@Component({
  selector: 'ds-kanban',
  standalone: true,
  imports: [CommonModule, DragDropModule],
  templateUrl: './ds-kanban.html',
})
export class DsKanbanComponent {
  columns = signal<KanbanColumn[]>([
    { id: 'todo', title: 'A Fazer', items: [{ id: '1', content: 'Desenvolver Header' }, { id: '2', content: 'Ajustar CSS' }] },
    { id: 'doing', title: 'Em Progresso', items: [{ id: '3', content: 'Criar Kanban' }] },
    { id: 'done', title: 'Concluído', items: [] }
  ]);

  drop(event: CdkDragDrop<any[]>) {
    if (event.previousContainer === event.container) {
      moveItemInArray(event.container.data, event.previousIndex, event.currentIndex);
    } else {
      transferArrayItem(
        event.previousContainer.data,
        event.container.data,
        event.previousIndex,
        event.currentIndex
      );
    }
  }
}

import { Component, Input, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';

export interface Step {
  label: string;
  description?: string;
}

@Component({
  selector: 'ds-stepper',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './ds-stepper.html',
  styleUrl: './ds-stepper.scss',
})
export class DsStepperComponent {
  @Input({ required: true }) steps: Step[] = [];

  currentStep = signal(0);

  progressWidth = computed(() => {
    return (this.currentStep() / (this.steps.length - 1)) * 100;
  });

  next() {
    if (this.currentStep() < this.steps.length - 1) {
      this.currentStep.update(s => s + 1);
    }
  }

  prev() {
    if (this.currentStep() > 0) {
      this.currentStep.update(s => s - 1);
    }
  }
}

import { Component, Input, signal, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DsInputComponent } from '../../atoms/ds-input/ds-input';
export interface TableColumn {
  label: string;
  key: string;
  sortable?: boolean;
}

@Component({
  selector: 'ds-table',
  standalone: true,
  imports: [CommonModule, DsInputComponent],
  templateUrl: './ds-table.html',

})
export class DsTable<T> {
  @Input() columns: TableColumn[] = [];

  /** Paginação */
  @Input() pageSize = 10;
  readonly pageSizeOptions = [10, 25, 50] as const;

  // Sinais de Estado
  rawDataSource = signal<any[]>([]);
  filterText = signal('');
  sortConfig = signal<{ key: string, direction: 'asc' | 'desc' | null }>({ key: '', direction: null });
  currentPage = signal(1); // 1-based

  @Input() set dataSource(value: T[]) {
    this.rawDataSource.set(value);
  }

  // A MÁGICA: Dados filtrados e ordenados automaticamente
  filteredData = computed(() => {
    let data = [...this.rawDataSource()];
    const filter = this.filterText().toLowerCase();

    // 1. Filtragem
    if (filter) {
      data = data.filter(row => 
        Object.values(row).some(val => String(val).toLowerCase().includes(filter))
      );
    }

    // 2. Ordenação
    const sort = this.sortConfig();
    if (sort.key && sort.direction) {
      data.sort((a, b) => {
        const valA = a[sort.key];
        const valB = b[sort.key];
        if (sort.direction === 'asc') return valA > valB ? 1 : -1;
        return valA < valB ? 1 : -1;
      });
    }

    return data;
  });

  totalItems = computed(() => this.filteredData().length);

  totalPages = computed(() => {
    const size = Math.max(1, this.pageSize || 1);
    return Math.max(1, Math.ceil(this.totalItems() / size));
  });

  pagedData = computed(() => {
    const data = this.filteredData();
    const size = Math.max(1, this.pageSize || 1);
    const page = Math.min(Math.max(1, this.currentPage()), this.totalPages());
    const start = (page - 1) * size;
    return data.slice(start, start + size);
  });

  pageNumbers = computed(() => {
    const total = this.totalPages();
    const current = this.currentPage();
    const maxButtons = 5;

    if (total <= maxButtons) return Array.from({ length: total }, (_, i) => i + 1);

    let start = Math.max(1, current - 2);
    let end = Math.min(total, start + (maxButtons - 1));
    start = Math.max(1, end - (maxButtons - 1));
    return Array.from({ length: end - start + 1 }, (_, i) => start + i);
  });

  onFilter(event: Event) {
    const val = (event.target as HTMLInputElement).value;
    this.filterText.set(val);
    this.currentPage.set(1);
  }

  toggleSort(key: string) {
    const current = this.sortConfig();
    if (current.key === key) {
      const nextDir = current.direction === 'asc' ? 'desc' : 'asc';
      this.sortConfig.set({ key, direction: nextDir });
    } else {
      this.sortConfig.set({ key, direction: 'asc' });
    }
    this.currentPage.set(1);
  }

  goToPage(page: number) {
    const next = Math.min(Math.max(1, page), this.totalPages());
    this.currentPage.set(next);
  }

  nextPage() {
    this.goToPage(this.currentPage() + 1);
  }

  prevPage() {
    this.goToPage(this.currentPage() - 1);
  }

  setPageSize(size: number) {
    const next = Math.max(1, Number(size) || 10);
    this.pageSize = next;
    this.currentPage.set(1);
  }

  onPageSizeChange(event: Event) {
    const target = event.target as HTMLSelectElement | null;
    this.setPageSize(target?.value ? Number(target.value) : this.pageSize);
  }
}

import { Injectable, signal } from '@angular/core';

export interface Toast {
  id: number;
  message: string;
  type: 'success' | 'error' | 'info';
}

@Injectable({ providedIn: 'root' })
export class ToastService {
  // Um Signal que armazena uma lista de toasts ativos
  toasts = signal<Toast[]>([]);

  show(message: string, type: 'success' | 'error' | 'info' = 'success') {
    const id = Date.now();
    this.toasts.update(all => [...all, { id, message, type }]);

    // Remove automaticamente após 3 segundos
    setTimeout(() => {
      this.toasts.update(all => all.filter(t => t.id !== id));
    }, 3000);
  }
}

